use std::{fs,path::Path,collections::BTreeMap};use serde_json::{Value,json};use sha2::{Sha256,Digest};const R:&str="/home/ubuntu/src/zopro-perf-work/group-pmu214";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn med(mut v:Vec<f64>)->f64{v.sort_by(f64::total_cmp);v[v.len()/2]}
fn main(){let smoke_only=std::env::args().nth(1).as_deref()==Some("smoke");let r=Path::new(R);let old=read("/home/ubuntu/src/zopro-perf-work/group-cpu211/source/.xtask/source-pins.json");let mut retained=0;let mut changed=vec![];for(p,h)in old.as_object().unwrap(){let rel=p.strip_prefix("/home/ubuntu/src/zopro-perf-work/group-cpu211/source/").unwrap();if hash(r.join("source").join(rel))==h.as_str().unwrap(){retained+=1;}else{changed.push(rel);}}assert_eq!(retained,180);assert_eq!(changed,vec!["crates/zopro-core/src/boolean_phase_trace.rs"]);assert_eq!(hash(r.join("source/crates/zopro-core/src/boolean_phase_trace/pmu.rs")),hash(r.join("pmu.rs")));
let mut rows=vec![];let mut active=0;let mut zeros=0;let mut mincoverage=1f64;let mut quality=true;let mut initialized=0;for j in read(r.join("jobs.json")).as_array().unwrap(){let smoke=j["smoke"]==true;if smoke_only&&!smoke{continue;}let name=j["name"].as_str().unwrap();let d=r.join(format!("{}-run/{name}",if smoke{"smoke"}else{"main"}));let e=read(d.join("exit.json"));assert_eq!(e["returncode"],0);assert_eq!(hash(d.join("stdout.log")),e["stdout_sha256"]);let out=fs::read_to_string(d.join("stdout.log")).unwrap();let setups=out.lines().filter_map(|l|l.strip_prefix("PMU_SETUP ")).map(|s|serde_json::from_str::<Value>(s).unwrap()).collect::<Vec<_>>();assert_eq!(setups.len(),1);assert_eq!(setups[0]["workers"],j["workers"]);assert_eq!(setups[0]["euid"],0);assert_eq!(setups[0]["events"],json!(["cycles:u","instructions:u"]));initialized+=1;
let mut metrics=BTreeMap::<&str,Vec<f64>>::new();let mut n=0;let mut localcoverage=1f64;for s in out.lines().filter_map(|l|l.strip_prefix("PHASE ")){let v:Value=serde_json::from_str(s).unwrap();let p:Vec<u64>=serde_json::from_value(v["group_pmu"].clone()).unwrap();assert_eq!(p.len(),8);n+=1;if j["trace"]==false{assert_eq!(p,[0;8]);zeros+=1;continue;}let mut delta=[0u64;4];for i in 0..4{assert!(p[2*i+1]>=p[2*i]);delta[i]=p[2*i+1]-p[2*i];assert!(delta[i]>0);}let coverage=delta[3]as f64/delta[2]as f64;mincoverage=mincoverage.min(coverage);localcoverage=localcoverage.min(coverage);quality&=coverage>=0.99&&delta[3]<=delta[2]+1000;active+=1;for(k,v)in[("cycles",delta[0]as f64),("instructions",delta[1]as f64),("CPI",delta[0]as f64/delta[1]as f64),("enabled_ns",delta[2]as f64),("running_ns",delta[3]as f64),("coverage",coverage)]{metrics.entry(k).or_default().push(v);}}
assert_eq!(n,j["rounds"].as_u64().unwrap());if j["trace"]==true{rows.push(json!({"job":j,"records":n,"minimum_coverage":localcoverage,"median":metrics.into_iter().map(|(k,v)|(k,med(v))).collect::<BTreeMap<_,_>>()}));}}
let mut paired=vec![];if !smoke_only{assert_eq!(initialized,16);assert_eq!(active,1508);assert_eq!(zeros,1508);for block in 0..3{let get=|b:bool|rows.iter().find(|r|r["job"]["smoke"]==false&&r["job"]["boolean"]==b&&r["job"]["block"]==block).unwrap();let mut ratios=BTreeMap::new();for k in["cycles","instructions","CPI"]{ratios.insert(k,get(true)["median"][k].as_f64().unwrap()/get(false)["median"][k].as_f64().unwrap());}paired.push(json!({"block":block,"OFF":get(false),"ON":get(true),"ratios":ratios}));}}
let observer_ok=smoke_only||read(r.join("result.json"))["ready_to_interpret"]==true;let result=json!({"pass":true,"quality_pass":quality,"observer_pass":observer_ok,"ready_to_interpret":quality&&observer_ok,"diagnostic_only":true,"source211_retained":180,"source211_PMU_modified":1,"new_PMU_module":1,"initialized_processes":initialized,"active_records":active,"zero_records":zeros,"minimum_coverage":mincoverage,"rows":rows,"paired_blocks":paired,"no_adoption_claim":true});let p=r.join(if smoke_only{"pmu-smoke.json"}else{"pmu-result.json"});assert!(!p.exists());fs::write(p,serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("PMUschema/IDsverifiedbyproducer;quality={quality},observer={observer_ok},active{active}/zero{zeros},mincoverage{mincoverage}");assert!(quality,"PMUqualityfailed; do notinterpret orstartmorecapture");}
